@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

[] a sh:ValidationReport ;
    sh:conforms false ;
    sh:result [ a sh:ValidationResult ;
            sh:focusNode <ex:laQicpmsTAPP-P6> ;
            sh:resultMessage "LaserAblation requires ada:elementalFractionationCorrection on the procedure." ;
            sh:resultPath ada:elementalFractionationCorrection ;
            sh:resultSeverity sh:Warning ;
            sh:sourceConstraintComponent sh:MinCountConstraintComponent ;
            sh:sourceShape [ sh:message "LaserAblation requires ada:elementalFractionationCorrection on the procedure." ;
                    sh:minCount 1 ;
                    sh:path ada:elementalFractionationCorrection ;
                    sh:severity sh:Warning ] ] .

@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

[] a sh:ValidationReport ;
    sh:conforms true .

